# Auto-generated by Intelligent Terminal. Do not edit between markers.
# Documents is resolved at runtime so this survives OneDrive Known
# Folder Move and is a silent no-op on machines without IT installed.
$__it_si = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'PowerShell\shell-integration_v11.ps1'
if (Test-Path -LiteralPath $__it_si) { . $__it_si }
Remove-Variable __it_si -ErrorAction SilentlyContinue
# <<< intelligent-terminal shell-integration <<<

Import-Module Terminal-Icons
Import-Module z

# Predictions need an interactive console; skip when output is redirected (scripts, CI, tools)
if (-not [Console]::IsOutputRedirected) {
    Set-PSReadLineOption -PredictionSource History
}
Set-PSReadLineOption -EditMode Windows

oh-my-posh init pwsh --config jandedobbeleer | Invoke-Expression

# Personal env vars / aliases, copied next to this profile by install.ps1
foreach ($file in '.exports.ps1', '.aliases.ps1') {
    $path = Join-Path $PSScriptRoot $file
    if (Test-Path $path) { . $path }
}
Remove-Variable file, path -ErrorAction SilentlyContinue
